function xml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function unxml(value){return String(value??'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');}
function tag(source,name){const m=String(source||'').match(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'i'));return m?unxml(m[1].trim()):null;}
function blocks(source,name){return[...String(source||'').matchAll(new RegExp(`<(?:\\w+:)?${name}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/(?:\\w+:)?${name}>`,'gi'))].map(m=>m[1]);}
function allTags(source,name){return blocks(source,name).map(v=>unxml(v.trim())).filter(Boolean);}
function parseMoney(value){const n=Number(String(value??'').replace(',','.').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null;}
function randomRef(prefix='KR'){return `${prefix}${Date.now().toString(36).toUpperCase()}${crypto.randomBytes(4).toString('hex').toUpperCase()}`.slice(0,25);}
function sha(value){return crypto.createHash('sha256').update(String(value||'')).digest('hex');}
function zaToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Johannesburg',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function compactStatus(raw){const t=String(raw||'').trim();if(!t||/FILE NOT READY/i.test(t))return{ready:false,status:'file_not_ready'};const begin=t.split(/\r?\n/).find(l=>l.startsWith('###BEGIN'))||'';const state=String(begin.split('\t')[2]||'').trim().toUpperCase();if(state==='SUCCESSFUL')return{ready:true,status:'successful'};if(state==='SUCCESSFUL WITH ERRORS')return{ready:true,status:'successful_with_errors'};if(state==='UNSUCCESSFUL'||t.includes('###ERROR')||/^(100|102|200)$/.test(t))return{ready:true,status:'unsuccessful'};return{ready:false,status:'processing'};}
function soapError(text,status,label='Netcash'){return new HttpError(status>=500?502:400,tag(text,'faultstring')||tag(text,'Text')||tag(text,'Reason')||`${label} returned HTTP ${status}.`,'netcash_error');}

async function soap11(endpoint,method,body,namespace='http://tempuri.org/',timeout=30000){
  const action=`${namespace}${method}`;
  const envelope=`<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><${method} xmlns="${namespace}">${body}</${method}></soap:Body></soap:Envelope>`;
  const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/xml; charset=utf-8',SOAPAction:`"${action}"`},body:envelope,signal:AbortSignal.timeout(timeout)});
  const text=await response.text();if(!response.ok||/<(?:\w+:)?Fault[\s>]/i.test(text))throw soapError(text,response.status,method);return text;
