function creditorInstruction(stream){return stream==='rtc'?'RTCPayments':stream==='dated'?'DatedPayments':'Realtime';}
function buildCreditorFile({serviceKey,svk,batchName,actionDate,payout,loan,profile}){
  const keys=[101,102,131,132,133,134,135,136,162,201,202,252,301,302,303];
  const holder=String(profile.bank_account_holder||`${profile.first_name||''} ${profile.last_name||''}`).trim();
  const row=[`K\t${keys.join('\t')}`,
    ['T',loan.account_number||payout.id,String(`${profile.first_name||''} ${profile.last_name||''}`).trim(),1,holder,bankAccountTypeCode(profile.bank_account_type),String(profile.branch_code||'').replace(/\D/g,'').padStart(6,'0'),0,String(profile.bank_account_number||'').replace(/\D/g,''),Math.round(Number(payout.amount)*100),profile.email||'',String(profile.mobile||'').replace(/\D/g,'').slice(-10),String(loan.account_number||'KredRun loan').slice(0,20),payout.id,loan.id,loan.user_id].join('\t')];
  return [`H\t${serviceKey}\t1\t${creditorInstruction(payout.stream)}\t${batchName}\t${yyyymmdd(actionDate)}\t${svk||NETCASH_DEFAULT_SVK}`,...row,'F\t1\t0\t9999'].join('\n');
}

async function findUnauthorisedBatch(serviceKey,batchName){
  const text=await nif('RetrieveUnauthorisedBatches',{ServiceKey:serviceKey});const result=tag(text,'RetrieveUnauthorisedBatchesResult')||tag(text,'String')||text;
  for(const line of String(result).split(/\r?\n/)){const f=line.split('\t');if(f.includes(batchName)||String(line).includes(batchName))return{batchId:String(f[1]||f[0]||'').trim(),raw:line};}return null;
}
export async function authoriseNetcashBatch(serviceKey,batchName){
  const{config}=await context();if(!config.auto_batch_authorization_enabled||!config.auto_batch_authorization_indemnity_confirmed)throw new HttpError(409,'Automatic batch authorisation is not enabled and indemnity-confirmed for this Netcash account.','netcash_auto_authorisation_not_enabled');
  const batch=await findUnauthorisedBatch(serviceKey,batchName);if(!batch?.batchId)throw new HttpError(409,'Netcash did not return this batch as unauthorised.','netcash_batch_not_found');
  const text=await nif('RequestBatchAuthorise',{ServiceKey:serviceKey,BatchId:batch.batchId});const result=String(tag(text,'RequestBatchAuthoriseResult')||'').trim();
