}

export async function disburseNetcashLoan({loanId,stream=null,createdBy=null}){
  const{config,credentials}=await context();requireEnabled(config);if(!config.creditor_payments_enabled)throw new HttpError(409,'Netcash Creditor Payments are disabled in Settings.','netcash_creditor_disabled');
