    const updated=(await dbUpdate('netcash_payouts',{id:`eq.${payout.id}`},{status:auth.status==='authorised'?'authorised':'unauthorised',batch_name:batchName,file_token:fileToken,batch_id:auth.batchId,authorisation_status:auth.status,load_status:report.status,provider_result:{load_report:String(raw).slice(0,12000),controls},submitted_at:new Date().toISOString(),updated_at:new Date().toISOString()}))?.[0];
    await dbUpdate('loans',{id:`eq.${loan.id}`},{payout_provider:'netcash',payout_provider_status:updated?.status||'unauthorised',updated_at:new Date().toISOString()});return{payout:updated||payout,controls};
  }catch(error){await dbUpdate('netcash_payouts',{id:`eq.${payout.id}`},{status:'failed',last_error:String(error.message||error).slice(0,500),updated_at:new Date().toISOString()}).catch(()=>{});throw error;}
