export async function submitCreditCardDebitOrder({loanId,scheduleId,cardTokenId,actionDate=null,instruction='same_day',createdBy=null}){const{config,credentials}=await context();requireEnabled(config);if(!config.credit_card_debit_orders_enabled)throw new HttpError(409,'Credit-card debit orders are disabled.','card_debit_disabled');const key=requireKey(credentials,'debitOrderServiceKey','Debit Order Service Key');const loan=(await dbSelect('loans',{select:'*',id:`eq.${loanId}`,limit:1}))?.[0],schedule=(await dbSelect('repayment_schedule',{select:'*',id:`eq.${scheduleId}`,limit:1}))?.[0],card=(await dbSelect('netcash_card_tokens',{select:'*',id:`eq.${cardTokenId}`,limit:1}))?.[0];if(!loan||!schedule||!card||card.user_id!==loan.user_id)throw new HttpError(409,'Loan, instalment and tokenised card must belong to the same client.','card_debit_context_invalid');const remaining=Number(schedule.amount_due)-Number(schedule.amount_paid||0);if(!(remaining>0))throw new HttpError(409,'This instalment has no amount left to collect.','instalment_paid');const inst=instruction==='two_day'?'TwoDay':'SameDay';const requested=actionDate||schedule.due_date||zaToday();const validDate=await requestActionDate(key,requested,inst,true)||requested;const created=(await dbInsert('netcash_card_debit_orders',{user_id:loan.user_id,loan_id:loan.id,schedule_id:schedule.id,card_token_id:card.id,amount:remaining,action_date:validDate,instruction,status:'initializing',created_by:createdBy}))?.[0];const batchName=`KR-CARD-${Date.now().toString(36)}`;const cardType=String(card.card_type||'').toLowerCase().includes('visa')?2:1;const file=[`H\t${key}\t1\t${inst}\t${batchName}\t${yyyymmdd(validDate)}\t${config.software_vendor_key||NETCASH_DEFAULT_SVK}`,'K\t101\t102\t131\t132\t133\t134\t135\t136\t137\t162\t301\t302\t303',['T',loan.account_number||created.id,String(card.card_name||'Cardholder'),2,card.card_name||'',cardType,String(card.expiry_month||'').padStart(2,'0'),String(card.expiry_year||''),card.provide